pub(crate) fn check_core_stmt_for_a_range(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, iter: &Expr, frame: &mut Vec<CheckLocal>, span: &Span) {
    match iter {
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            let mut open: Vec<i64> = vec![];
            for n in state.open_numbers_in(world, start) { open.push(n); }
            for n in state.open_numbers_in(world, end) { open.push(n); }
            state.open_numbers_joined(&open);
            if !open.is_empty() && !frame.is_empty() { frame[0].open_number = Some(state.open_root(*nikaia_std::index::get(&open, 0))); }
            if open.is_empty() && state.number_shaped(world, start) && state.number_shaped(world, end) && !frame.is_empty() && nikaia_std::index::get(&frame, 0).ty.is_unknown() {
                let first: String = nikaia_std::index::get(&frame, 0).name.to_owned();
                state.flow.open_numbers.insert(span.start as i64, check_core_stmt_open_number(&first, false, span));
                frame[0].open_number = Some(span.start as i64);
                state.open_number_given(world, span.start as i64, start, span);
                state.open_number_given(world, span.start as i64, end, span);
            }
        },
        _ => { },
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
#[allow(clippy::too_many_arguments)]
pub fn check_core_stmt_for<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, bindings: &[winnow_grammar::Symbol], shape: &[i64], iter: &Expr, body: &Block, span: &Span) -> Ty {
    state.the_caller_writes_no_reference(iter, span, "a `for` lends what it iterates");
    let over = check_core_expr(state, world, host, iter, span);
    state.a_loop_over_a_nullable(world, &over, iter, span);
    let mut width = bindings.len() as i64;
    if !shape.is_empty() && *nikaia_std::index::get(&shape, 0) > 0 { width = *nikaia_std::index::get(&shape, 0); }
    let before = state.findings.len() as i64;
    state.fallible_step(world, &over, width, span);
    let stepped_fallibly = (state.findings.len() as i64) > before;
    state.pausing_step(&over, span);
    state.a_sequence_is_walked(iter, &over, span, world);
    let mut elements = elements_walked(&over, width);
    if width > 1 && !stepped_fallibly { let refused = state.a_tuple_pattern_that_does_not_fit(&element_walked(&over, 1), width, "A `for`", span); }
    if !shape.is_empty() { elements = state.nested_pattern_parts(world, elements, shape, bindings.len() as i64, "A `for`", span); }
    if bindings.len() == 1 && state.current.is_some() && check_core_stmt_holds_code(&over) {
        let current: String = nikaia_std::index::or(match state.current.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "".into());
        let to = format!("{}::{}", current, world.words.resolve(*nikaia_std::index::get(&bindings, 0)));
        let keys = check_core_places_code_keys(&state, world, iter);
        let mut entry: CheckStoredCode = nikaia_std::index::or(state.stored_code.remove(&to), || CheckStoredCode::empty());
        if keys.is_empty() { entry.unresolved = true; }
        for from in keys.iter() {
            let given: CheckStoredCode = nikaia_std::index::or(match *nikaia_std::index::get(&state.stored_code, from) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || CheckStoredCode { resolved: collections::BTreeSet::new(), unresolved: true, free: collections::BTreeSet::new() });
            for resolved in given.resolved.iter() { entry.resolved.insert(resolved.to_owned()); }
            entry.unresolved = entry.unresolved || given.unresolved;
            for free in given.free.iter() { entry.free.insert(free.to_owned()); }
        }
        state.stored_code.insert(to, entry);
    }
    let a_seq = matches!(over, Ty::Seq { .. });
    let owned = is_a_place(iter) && a_seq;
    if owned { state.facts.owned_loops.insert(span.start as i64); }
    let lent = is_a_place(iter) && !owned;
    let mut frame: Vec<CheckLocal> = vec![];
    let mut at: i64 = 0;
    for b in bindings.iter() {
        let b = *b;
        if ((at) as usize) >= elements.len() { break; }
        let name: String = format!("{}", world.words.resolve(b));
        let element = (*nikaia_std::index::get(&elements, (at) as usize)).clone();
        at += 1;
        let copied = lent && name != "_" && a_copy_by_value(&element);
        if copied { state.facts.copied_loop_bindings.insert((span.start as i64, name.to_owned())); }
        let declared_copy = lent && name != "_" && !copied && !element.is_a_view() && state.a_view_that_copies(world, &view_of_type(&element));
        let a_view = declared_copy || lent && name != "_" && !copied && element.is_a_view();
        if a_view { state.facts.copied_view_bindings.insert((span.start as i64, name.to_owned())); }
        let named = matches!(element, Ty::Named { .. });
        let mut bound = element.clone();
        if lent && !copied && !declared_copy && named { bound = view_of_type(&element); }
        let id = state.a_new_binding();
        let mut local = CheckLocal::free(name, bound, id);
        local.written_mut = false;
        local.lent = lent && !copied && !a_view;
        local.immutable = Some(CheckImmutable { at: Span { start: span.start, end: span.end }, kind: CheckKind::Loop });
        frame.push(local);
    }
    if bindings.len() == 1 { check_core_stmt_for_a_range(state, world, iter, &mut frame, span); }
    if bindings.len() == 1 && !frame.is_empty() && nikaia_std::index::get(&frame, 0).ty.is_unknown() {
        match iter {
            Expr::Variable(name, _) => {
                let name = *name;
                let named: String = format!("{}", world.words.resolve(name));
                let list = state.binding(&named);
                if list.is_some() {
                    let held: CheckLocal = match list { Some(__nikaia_value) => __nikaia_value, None => return check_core_stmt_unit() };
                    let element_at = state.flow.open_elements.get(&held.id);
                    if element_at.is_some() {
                        let element: i64 = nikaia_std::index::or(element_at, || 0);
                        frame[0].open_number = Some(state.open_root(element));
                    }
                }
            },
            Expr::ListLit { items, .. } => {
                let mut all_numbers = !items.is_empty();
                for item in items.iter() { if all_numbers && !state.number_shaped(world, item) { all_numbers = false; } }
                if all_numbers {
                    let first: String = nikaia_std::index::get(&frame, 0).name.to_owned();
                    state.flow.open_numbers.insert(span.start as i64, check_core_stmt_open_number(&first, false, span));
                    frame[0].open_number = Some(span.start as i64);
                    for item in items.iter() { state.open_number_given(world, span.start as i64, item, span); }
                }
            },
            _ => { },
        }
    }
    if bindings.len() == 2 && frame.len() == 2 {
        match iter {
            Expr::Variable(name, _) => {
                let name = *name;
                let named: String = format!("{}", world.words.resolve(name));
                let map = state.binding(&named);
                if map.is_some() {
                    let held: CheckLocal = match map { Some(__nikaia_value) => __nikaia_value, None => return check_core_stmt_unit() };
                    let a_map = match held.ty {
                        Ty::Named { ref name, .. } => a_map_type(name),
                        _ => false,
                    };
                    let keys = state.flow.open_keys.get(&held.id);
                    if a_map && keys.is_some() && nikaia_std::index::get(&frame, 0).ty.is_unknown() { frame[0].open_number = Some(state.open_root(nikaia_std::index::or(keys, || 0))); }
                    let values = state.flow.open_elements.get(&held.id);
                    if a_map && values.is_some() && nikaia_std::index::get(&frame, 1).ty.is_unknown() { frame[1].open_number = Some(state.open_root(nikaia_std::index::or(values, || 0))); }
                }
            },
            _ => { },
        }
    }
    for local in frame.iter() { state.nameable(&local.name, span, "a `for` binding"); }
    let depth = state.scope.len() as i64;
    state.repeats.push(CheckRepeats::a_loop(world.words, depth, body));
    state.scope.push(frame);
    state.flow.loops += 1;
    check_core_stmt_body_discarded(state, body);
    check_core_block(state, world, host, body);
    state.flow.loops -= 1;
    state.scope.pop();
    state.repeats.pop();
    check_core_stmt_unit()
}

